const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const kabul = ee.Geometry.Point([69.2075, 34.5553]);
    const radiusMeters = 30 * 1609.34; // 30 miles in meters
    const region = kabul.buffer(radiusMeters);

    const feb2017Start = '2017-02-01';
    const feb2017End = '2017-03-01';
    const feb2018Start = '2018-02-01';
    const feb2018End = '2018-03-01';

    // 2. Data Acquisition - ERA5-Land Monthly
    const collection = ee.ImageCollection('ECMWF/ERA5_LAND/MONTHLY');
    const feb2017 = collection
        .filterDate(feb2017Start, feb2017End)
        .filterBounds(region)
        .select('temperature_2m');
    const feb2018 = collection
        .filterDate(feb2018Start, feb2018End)
        .filterBounds(region)
        .select('temperature_2m');

    // Check collection sizes
    const count2017 = feb2017.size().getInfo();
    const count2018 = feb2018.size().getInfo();

    console.log(`2017 Images: ${count2017}`);
    console.log(`2018 Images: ${count2018}`);

    if (count2017 === 0 || count2018 === 0) {
        console.log("<answer>C1</answer>");
        return;
    }

    // Get monthly mean images (each collection should have 1 image)
    const img2017 = feb2017.mean();
    const img2018 = feb2018.mean();

    // 3. Processing - Get stats with count
    const reducer = ee.Reducer.mean().combine(ee.Reducer.count(), null, true);

    const stats2017 = img2017.reduceRegion({
        reducer: reducer,
        geometry: region,
        scale: 10000,
        maxPixels: 1e9
    });
    const stats2018 = img2018.reduceRegion({
        reducer: reducer,
        geometry: region,
        scale: 10000,
        maxPixels: 1e9
    });

    const mean2017 = stats2017.get('temperature_2m_mean');
    const countPix2017 = stats2017.get('temperature_2m_count');
    const mean2018 = stats2018.get('temperature_2m_mean');
    const countPix2018 = stats2018.get('temperature_2m_count');

    const [m2017, cnt2017, m2018, cnt2018] = await Promise.all([
        mean2017.getInfo(),
        countPix2017.getInfo(),
        mean2018.getInfo(),
        countPix2018.getInfo()
    ]);

    console.log(`Feb 2017 Temp: ${(m2017 - 273.15).toFixed(2)}°C (Pixels: ${cnt2017})`);
    console.log(`Feb 2018 Temp: ${(m2018 - 273.15).toFixed(2)}°C (Pixels: ${cnt2018})`);

    // 4. Validation & Final Answer
    if (cnt2017 === 0 || cnt2018 === 0) {
        console.log("<answer>C2</answer>");
        return;
    }

    if (m2017 === null || m2018 === null || 
        isNaN(m2017) || isNaN(m2018) ||
        m2017 < 200 || m2017 > 350 ||   // Rough validity checks for Kelvin
        m2018 < 200 || m2018 > 350) {
        console.log("<answer>C3</answer>");
        return;
    }

    if (m2018 > m2017) {
        console.log("<answer>A</answer>");
    } else {
        console.log("<answer>B</answer>");
    }
}

